children.blockClientScript:
if (block_data.same_address) this.setAttribute("checked", block_data.same_address);
this.addEventListener("change", async (e) => {
  console.log(e);
  if (this.checked) {
    await frappe_call(
      "POST",
      "webshop.webshop.shopping_cart.cart.update_cart_address",
      {
        address_type: "billing",
        address_name: block_data.shipping_address_name,
      }
    );
    window.location.reload();
    return;
  }
  dispatch("open-address-modal", { addressType: "billing" });
});

 this.addEventListener("click", async () => {
  try {
    const { item_code, qty } = block_data;
    await frappe_call(
      "POST",
      "webshop.webshop.shopping_cart.cart.update_cart",
      { item_code, qty: qty - 1 }
    );
    window.location.reload();
  } catch (e) {
    console.err(e);
    dispatch("show-toast", {
      message: "Could not edit quantity in cart!",
      type: "error",
    });
  }
});

this.addEventListener("click", async () => {
  try {
    const { item_code, qty } = block_data;
    await frappe_call(
      "POST",
      "webshop.webshop.shopping_cart.cart.update_cart",
      { item_code, qty: qty + 1 }
    );
    window.location.reload();
  } catch (e) {
    console.err(e);
    dispatch("show-toast", {
      message: "Could not edit quantity",
      type: "error",
    });
  }
});

let isCouponCodeFormOpen = false;

this.addEventListener("click", () => {
  let action;
  if (isCouponCodeFormOpen) {
    action = "close";
  } else {
    action = "open";
  }
  dispatch(`${action}-coupon-code-form`);
  isCouponCodeFormOpen = !isCouponCodeFormOpen;
});

const couponCodeInput = document.querySelector("#coupon-code-input");

this.addEventListener("click", async () => {
  if (couponCodeInput) {
    const couponCode = couponCodeInput.value;
    if (couponCode) {
      try {
        await frappe_call(
          "POST",
          "webshop.webshop.shopping_cart.cart.apply_coupon_code",
          { applied_code: couponCode }
        );
        window.location.reload();
      } catch (error) {
        dispatch("show-toast", {
          type: "error",
          message:
            "Could not apply coupon code! Please check if correct code is provided.",
        });
      }
    } else {
      dispatch("show-toast", {
          type: "warning",
          message:
            "No coupon code provided!",
        });
    }
  }
});

listen("open-address-modal", (e) => {
  this.style.top = "0px";
  this.style.left = "0px";
  console.log(e)
  if (e.detail.addressType == "shipping") {
    this.querySelector(".shipping-address-selector").style.display = "flex";
    this.querySelector(".billing-address-selector").style.display = "none";
  } else {
    this.querySelector(".shipping-address-selector").style.display = "none";
    this.querySelector(".billing-address-selector").style.display = "flex";
  }
});

listen("close-address-modal", (e) => {
  this.style.top = "-200%";
  this.style.left = "0px";
});
